 public static class ReviewValidation0535 {
  static void Check(bool v,string s){if(!v)throw new Exception(s);}
  static RoomView Load(string folder,string n){var v=JsonUtility.FromJson<RoomView>(File.ReadAllText(Path.Combine(folder,n+".json")));v.audioEvents=new PublicSound[0];v.handSeq=0;return v;}
