   // The winner's upright hand survives acceptance and the banner; polling retains it.
   foreach(int seat in new[]{1,2}){
    var win=JsonUtility.FromJson<RoomView>(File.ReadAllText(Path.Combine(folder,"win-3-tsumo-"+seat+"-0.json")));var before=Load(folder,"preview-3");before.audioRoom=win.audioRoom;before.audioSeq=win.audioSeq-1;before.turn=seat;client.ShowValidationFixture(before);fx.Accept(before);yield return null;fx.ValidationFreeze=true;fx.ValidationTime=.15f;client.ValidationApplyState(win);fx.Accept(win);yield return null;yield return null;
    var standing=GameObject.Find("Standing hand seat "+seat);Check(standing!=null&&standing.activeInHierarchy,"Opponent hand disappears on tsumo acceptance");yield return Shot(folder,"02-stand-before-tsumo-"+seat);table.Render(win);fx.Accept(win);yield return null;Check(standing.activeInHierarchy,"Polling creates empty hand interval");
    fx.ValidationTime=1.06f;yield return null;yield return null;fx.CutIn.Freeze=true;fx.CutIn.FrozenAge=1.3f;fx.ValidationTime=.1f;for(int i=0;i<5;i++)yield return null;Check(table.ValidationWinningRowVisible||standing.activeInHierarchy,"Gap between standing and pushed hand");yield return Shot(folder,"02-push-tsumo-"+seat);fx.Reset();fx.ValidationFreeze=false;
   }
