   }
   // Intro uses the whole effect viewport, allowing the native size curve to shrink.
   view=Load(folder,"preview-4");view.matchSeq=535;view.audioRoom="intro-0535";view.matchStartedAt=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();foreach(var player in view.players)player.river=new RiverTile[0];client.ShowValidationFixture(view);client.ValidationApplyState(view);client.ValidationIntro.Freeze=true;
   Check(MatchIntroduction.VictorySize(.02f)>MatchIntroduction.VictorySize(.25f)*1.6f,"Victory title lacks visible shrink");foreach(float age in new[]{1.22f,1.45f}){client.ValidationIntro.FrozenAge=age;yield return null;yield return Shot(folder,"03-victory-"+(age<1.3f?"large":"small"));}client.ValidationIntro.Reset();
   // North positions use adjacent scaled footprints; queued first/second tiles stay hidden.
   view=Load(folder,"preview-3");view.turn=0;view.audioRoom="north-0535";view.audioSeq=0;foreach(var player in view.players){player.nuki=0;player.melds=new string[0];}client.ShowValidationFixture(view);fx.Accept(view);yield return null;
   view.players[1].nuki=2;view.audioSeq=3;view.audioEvents=new[]{new PublicSound{id=1,seat=2,kind="discard",tile=view.players[2].river.Last().tile,riverIndex=view.players[2].river.Length},new PublicSound{id=2,seat=1,kind="nuki",tile="z4",nuki=1},new PublicSound{id=3,seat=1,kind="nuki",tile="z4",nuki=2}};fx.ValidationFreeze=true;fx.ValidationTime=.2f;client.ValidationApplyState(view);fx.Accept(view);yield return null;yield return null;Check(!table.NorthTarget(1,1).gameObject.activeSelf&&!table.NorthTarget(1,2).gameObject.activeSelf,"Queued North appears before its animation");yield return Shot(folder,"11-north-both-queued");table.Render(view);fx.Accept(view);yield return null;Check(!table.NorthTarget(1,1).gameObject.activeSelf&&!table.NorthTarget(1,2).gameObject.activeSelf,"Polling flashes queued North");
   fx.ValidationTime=.8f;yield return null;fx.ValidationTime=.25f;yield return null;yield return null;Check(fx.ValidationKind=="nuki"&&!table.NorthTarget(1,1).gameObject.activeSelf&&!table.NorthTarget(1,2).gameObject.activeSelf,"First carried North leaks onto cloth");yield return Shot(folder,"11-first-north-carried");fx.ValidationTime=fx.ValidationHandoff+.01f;yield return null;Check(table.NorthTarget(1,1).gameObject.activeSelf&&!table.NorthTarget(1,2).gameObject.activeSelf,"First landing exposes second North early");yield return Shot(folder,"11-first-north-landed");fx.ValidationTime=1.1f;yield return null;fx.ValidationTime=.25f;yield return null;yield return null;Check(table.NorthTarget(1,1).gameObject.activeSelf&&!table.NorthTarget(1,2).gameObject.activeSelf,"Second carried North hides first or leaks itself");yield return Shot(folder,"11-second-north-carried");fx.ValidationTime=fx.ValidationHandoff+.01f;yield return null;Check(table.NorthTarget(1,1).gameObject.activeSelf&&table.NorthTarget(1,2).gameObject.activeSelf,"Second North never lands");yield return Shot(folder,"11-second-north-landed");fx.Reset();fx.ValidationFreeze=false;
   foreach(int n in new[]{3,4}){view=Load(folder,"preview-"+n);foreach(var player in view.players){player.nuki=4;player.melds=new string[0];}client.ShowValidationFixture(view);yield return new WaitForSecondsRealtime(.25f);foreach(int seat in Enumerable.Range(0,n))for(int k=2;k<=4;k++){var a=table.NorthTarget(seat,k-1);var b=table.NorthTarget(seat,k);float gap=Mathf.Abs(a.localPosition.x-b.localPosition.x)-TableRenderer.MeldWidth*(a.localScale.x+b.localScale.x)/2;Check(Mathf.Abs(gap-.001f)<.003f,"North tile spacing differs from contact");}yield return Shot(folder,"06-north-contact-"+n);}
   // Own exhaustive-draw row shares the win width/spacing, with a distinct face-down position.
