   foreach(bool tenpai in new[]{true,false}){view=Load(folder,"draw-3-0");view.result.drawDetails[0].tenpai=tenpai;view.result.drawDetails[0].tiles=Load(folder,"preview-3").hand.Take(13).ToArray();client.ShowValidationFixture(view);yield return new WaitForSecondsRealtime(.75f);var row=Root(0,"Draw hand seat 0");var tiles=row.GetComponentsInChildren<BoxCollider>();Check(tiles.All(c=>Mathf.Abs(c.size.x-.35f)<.001f),"Own exhaustive row is smaller than win row");Check(Mathf.Abs(tiles[0].transform.localPosition.z+(tenpai?4.05f:4.34f))<.001f,"Face-up/down row has wrong edge");yield return Shot(folder,"08-draw-"+(tenpai?"face-up":"face-down"));}
   // AL triggers at scheduled last hand and extensions, repeats once per hand, not normal hands.
   foreach(int n in new[]{3,4})foreach(int rounds in new[]{1,2}){view=Load(folder,"preview-"+n);view.rounds=rounds;view.round=n*rounds-2;Check(!AllLastAnnouncement.IsLast(view),"AL triggers a hand early");view.round++;Check(AllLastAnnouncement.IsLast(view),"AL missing at scheduled last hand");view.round++;Check(AllLastAnnouncement.IsLast(view),"AL missing during extension");}
   view=Load(folder,"preview-4");view.audioRoom="last-0535";view.handSeq=535;view.round=3;view.rounds=1;view.dealtAt=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();view.openingHand=new string[0];foreach(var player in view.players)player.river=new RiverTile[0];client.ShowValidationFixture(view);client.ValidationApplyState(view);client.ValidationAllLast.Freeze=true;client.ValidationAllLast.FrozenAge=.5f;yield return null;Check(client.ValidationAllLast.Active,"Native AL missing");int starts=client.ValidationAllLast.Started;client.ValidationApplyState(view);Check(client.ValidationAllLast.Started==starts,"AL restarts on polling");yield return Shot(folder,"09-all-last");client.ValidationAllLast.Reset();
   var cue=new AllLastAnnouncement();view.dealtAt-=10000;cue.Observe(view);Check(!cue.Active,"Late reconnect replays AL");view.phase="result";cue.Observe(view);view.phase="play";view.handSeq++;view.honba++;cue.Observe(view);Check(cue.Active,"Known next hand misses AL with clock skew");
   Debug.Log("RIICHI REVIEW 0535 PASS: 50% larger/drift-safe wait hold and pre-discard candidates; opponent tsumo hand continuity through acceptance/polling; native win layout/3-to-1 scale in six positions; victory unclipped shrink; North adjacency and queued visibility; exhaustive own row .35 width and distinct face-up/down edges; AL rules and dedup. Item 10 is analysis only; AI tested independently.");
  }
 }
